LiteLlmModel::chat("claude-sonnet-4")
    .base_url("http://litellm:4000")
    .api_key(k)
    .build()?;

// POST /v1/chat/completions, SSE stream
// no metadata/tags/fallbacks/num_retries

// default: streaming + tools only
let m = LiteLlmModel::chat("prod-fast")
    .base_url(url).api_key(k).build()?;
assert!(m.capabilities().streaming);
assert!(!m.capabilities().vision);

// opt up explicitly
let m = LiteLlmModel::chat("prod-fast")
    .with_capabilities(
        ModelCapabilities::empty()
            .with_streaming().with_tools()
            .with_vision().with_structured_output())
    .build()?;

// sync, conservative
