    .base_url(url).api_key(k).build()?;

// OR opt in to a network probe
let m = LiteLlmModel::chat("prod-fast")
    .base_url(url).api_key(k)
    .discover().await?;   // GET /v1/model/info
// falls back to conservative on 404/None

// inferred from prefix
LiteLlmModel::chat("anthropic/claude-sonnet-4")
// -> vision + tools + structured_output

// but the common real-world case:
LiteLlmModel::chat("prod-fast")
// -> no prefix, falls back to conservative anyway

