//! Build per-transport request URLs and auth headers.

use paigasus_helikon_core::ModelError;

use crate::auth::Auth;
use crate::builder::{Config, Transport};

/// Host for the selected transport, honoring `base_url`.
fn host(cfg: &Config) -> String {
    if let Some(b) = &cfg.base_url {
        return b.trim_end_matches('/').to_owned();
    }
    match &cfg.transport {
        Transport::Developer => "https://generativelanguage.googleapis.com".to_owned(),
        Transport::Vertex { location, .. } if location == "global" => {
            "https://aiplatform.googleapis.com".to_owned()
        }
        Transport::Vertex { location, .. } => {
            format!("https://{location}-aiplatform.googleapis.com")
        }
    }
}

/// Streaming endpoint URL (`:streamGenerateContent?alt=sse`).
pub(crate) fn stream_url(cfg: &Config) -> String {
    let host = host(cfg);
    match &cfg.transport {
        Transport::Developer => format!(
            "{host}/v1beta/models/{}:streamGenerateContent?alt=sse",
            cfg.model_id
        ),
        Transport::Vertex { project, location } => format!(
            "{host}/v1/projects/{project}/locations/{location}/publishers/google/models/{}:streamGenerateContent?alt=sse",
            cfg.model_id
        ),
    }
}

/// Auth header for a non-async credential (`ApiKey`/`Bearer`).
pub(crate) fn auth_header(
    auth: &Auth,
) -> Result<(reqwest::header::HeaderName, String), ModelError> {
    use reqwest::header::{HeaderName, AUTHORIZATION};
    match auth {
        Auth::ApiKey(k) => Ok((HeaderName::from_static("x-goog-api-key"), k.clone())),
        Auth::Bearer(b) => Ok((AUTHORIZATION, format!("Bearer {b}"))),
        Auth::Token(_) => Err(ModelError::Other(anyhow::anyhow!(
            "Auth::Token must be resolved before auth_header"
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use paigasus_helikon_core::ModelCapabilities;

    fn dev_cfg() -> Config {
        Config {
            http: reqwest::Client::new(),
            base_url: None,
            model_id: "gemini-2.5-flash".into(),
            transport: Transport::Developer,
            auth: Auth::ApiKey("k".into()),
            capabilities: ModelCapabilities::empty(),
        }
    }
    fn vertex_cfg(loc: &str) -> Config {
        Config {
            http: reqwest::Client::new(),
            base_url: None,
            model_id: "gemini-2.5-pro".into(),
            transport: Transport::Vertex {
                project: "proj".into(),
                location: loc.into(),
            },
            auth: Auth::Bearer("ya29".into()),
            capabilities: ModelCapabilities::empty(),
        }
    }

    #[test]
    fn developer_stream_url() {
        let u = stream_url(&dev_cfg());
        assert_eq!(u, "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:streamGenerateContent?alt=sse");
    }

    #[test]
    fn vertex_regional_stream_url() {
        let u = stream_url(&vertex_cfg("us-central1"));
        assert_eq!(u, "https://us-central1-aiplatform.googleapis.com/v1/projects/proj/locations/us-central1/publishers/google/models/gemini-2.5-pro:streamGenerateContent?alt=sse");
    }

    #[test]
    fn vertex_global_host() {
        let u = stream_url(&vertex_cfg("global"));
        assert!(
            u.starts_with("https://aiplatform.googleapis.com/v1/projects/proj/locations/global/")
        );
    }

    #[test]
    fn base_url_override_developer() {
        let mut c = dev_cfg();
        c.base_url = Some("http://localhost:8080".into());
        assert_eq!(
            stream_url(&c),
            "http://localhost:8080/v1beta/models/gemini-2.5-flash:streamGenerateContent?alt=sse"
        );
    }

    #[test]
    fn api_key_header() {
        let (n, v) = auth_header(&Auth::ApiKey("secret".into())).unwrap();
        assert_eq!(n.as_str(), "x-goog-api-key");
        assert_eq!(v, "secret");
    }

    #[test]
    fn bearer_header() {
        let (n, v) = auth_header(&Auth::Bearer("ya29".into())).unwrap();
        assert_eq!(n.as_str(), "authorization");
        assert_eq!(v, "Bearer ya29");
    }
}

//! Google Gemini provider for the Paigasus Helikon SDK.
//!
//! # Overview
//!
//! This crate implements [`paigasus_helikon_core::Model`] for Google Gemini,
//! covering both the **Developer API** (API key) and **Vertex AI**
//! (OAuth bearer / [`TokenProvider`]).
//!
//! ## Public surface
//!
//! - [`GeminiModel`] — the `Model` implementation. Constructed via the fluent
//!   [`GeminiModelBuilder`] or the convenience shorthands below.
//! - [`GeminiModelBuilder`] — returned by [`GeminiModel::developer`] and
//!   [`GeminiModel::vertex`]. Call `.build()` to materialise the model.
//! - [`TokenProvider`] — trait for per-request Vertex bearer-token refresh.
//!   Implement it to supply rotating tokens (e.g. Workload Identity Federation).
//! - `AdcTokenProvider` (feature `vertex-adc`) — Application Default
//!   Credentials implementation backed by `gcp_auth`. Use
//!   `GeminiModel::vertex_from_env` for the one-call path.
//! - [`BuildError`] — validation errors raised by `.build()`.
//!
//! ## Transports
//!
//! **Developer API** — authenticates with an API key:
//!
//! ```ignore
//! use paigasus_helikon_providers_gemini::GeminiModel;
//! # fn f() -> Result<(), Box<dyn std::error::Error>> {
//! // Reads GEMINI_API_KEY or GOOGLE_API_KEY from the environment.
//! let model = GeminiModel::from_env("gemini-2.5-flash")?;
//! # Ok(()) }
//! ```
//!
//! **Vertex AI** — authenticates with a bearer token or [`TokenProvider`]:
//!
//! ```ignore
//! use paigasus_helikon_providers_gemini::GeminiModel;
//! # async fn f() -> Result<(), Box<dyn std::error::Error>> {
//! // vertex-adc feature: reads GOOGLE_CLOUD_PROJECT + GOOGLE_CLOUD_LOCATION.
//! let model = GeminiModel::vertex_from_env("gemini-2.5-flash").await?;
//! # Ok(()) }
//! ```
//!
//! ## Structured output
//!
//! Set `ModelSettings::response_format` to `ResponseFormat::JsonSchema`. The
//! provider passes the schema directly to Gemini's `generationConfig.responseSchema`
//! field (native structured output — no forced-tool synthesis). A JSON-Schema
//! sanitizer runs automatically to strip unsupported keywords and rewrite
//! incompatible constructs before sending.
//!
//! Note: Gemini rejects requests that combine `responseSchema` with active
//! function calling. The provider returns a conflict error before sending if
//! the request has non-empty tools OR a tool choice other than `None`.
//!
//! ## Limitations
//!
//! Remote-URL images, audio parts, and non-text tool-result parts are silently
//! dropped during request translation. Reasoning streaming (`ModelEvent::ReasoningDelta`)
//! is not yet emitted by this provider.

mod auth;
mod builder;
mod capabilities;
mod error;
mod model;
mod sse;
mod stream;
mod translate;
mod transport;

#[cfg(feature = "vertex-adc")]
pub use auth::AdcTokenProvider;
pub use auth::TokenProvider;
pub use builder::{BuildError, GeminiModelBuilder};
pub use model::GeminiModel;

